import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import sailpoint.connector.JDBCConnector;

// The default mapping takes all columns of the SELECT.
Map map = JDBCConnector.buildMapFromResultSet(result, schema);

String iiqid = (String) map.get("IIQID");
if (iiqid == null) {
    return map;
}

// Load the roles from the multi-value table.
List roles = new ArrayList();
PreparedStatement ps = null;
ResultSet rs = null;
try {
    ps = connection.prepareStatement(
        "SELECT \"RoleName\" FROM targetapp.\"IIQAccountRoles\" WHERE \"IIQID\" = ?");
    ps.setString(1, iiqid);
    rs = ps.executeQuery();
    while (rs.next()) {
        roles.add(rs.getString("RoleName"));
    }
} finally {
    // Close both separately: if closing the ResultSet fails, the
    // Statement must still be released, otherwise cursors pile up
    // on every aggregation.
    if (rs != null) {
        try { rs.close(); } catch (Exception e) { }
    }
    if (ps != null) {
        try { ps.close(); } catch (Exception e) { }
    }
}

map.put("roles", roles);

// Account state. IIQ recognises the reserved attribute IIQDisabled
// on the ResourceObject; without it every JDBC account shows as
// enabled regardless of the Status column.
map.put("IIQDisabled", "disabled".equalsIgnoreCase((String) map.get("Status")));
return map;

import java.sql.PreparedStatement;
import java.util.ArrayList;
import java.util.List;
import sailpoint.object.ProvisioningPlan;
import sailpoint.object.ProvisioningPlan.AttributeRequest;
import sailpoint.object.ProvisioningResult;
import sailpoint.tools.Util;

ProvisioningResult result = new ProvisioningResult();

// Collect the values from the plan.
java.util.Map values = new java.util.HashMap();
List roles = new ArrayList();

List attrs = request.getAttributeRequests();
if (attrs != null) {
    for (AttributeRequest attr : attrs) {
        String name = attr.getName();
        Object value = attr.getValue();
        if ("roles".equals(name)) {
            if (value instanceof List) {
                roles.addAll((List) value);
            } else if (value != null) {
                roles.add(value.toString());
            }
        } else if (value != null) {
            values.put(name, value.toString());
        }
    }
}

// IIQID is the schema's identityAttribute. The Provisioner moves
// that value out of the AttributeRequests into
// AccountRequest.nativeIdentity, so it is NOT in the map even
// though the create policy sets it. Measured: every role-driven
// create failed with "IIQID missing" while the request carried
// nativeIdentity="1075".
String iiqid = request.getNativeIdentity();
if (Util.isNullOrEmpty(iiqid)) {
    iiqid = (String) values.get("IIQID");
}
if (Util.isNullOrEmpty(iiqid)) {
    result.setStatus(ProvisioningResult.STATUS_FAILED);
    result.addError("IIQID missing, the account cannot be created.");
    return result;
}

PreparedStatement ps = null;
try {
    ps = connection.prepareStatement(
        "INSERT INTO targetapp.\"IIQData\" " +
        "(\"IIQID\", \"Account\", \"FirstName\", \"LastName\", \"Name\", " +
        " \"Email\", \"Phone\", \"Position\", \"Department\", \"Costcenter\", " +
        " \"Location\", \"EmploymentType\", \"Status\") " +
        "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)");

    ps.setString(1,  iiqid);
    ps.setString(2,  (String) values.get("Account"));
    ps.setString(3,  (String) values.get("FirstName"));
    ps.setString(4,  (String) values.get("LastName"));
    ps.setString(5,  (String) values.get("Name"));
    ps.setString(6,  (String) values.get("Email"));
    ps.setString(7,  (String) values.get("Phone"));
    ps.setString(8,  (String) values.get("Position"));
    ps.setString(9,  (String) values.get("Department"));
    ps.setString(10, (String) values.get("Costcenter"));
    ps.setString(11, (String) values.get("Location"));
    ps.setString(12, (String) values.get("EmploymentType"));
    ps.setString(13, values.get("Status") != null
                     ? (String) values.get("Status") : "active");
    ps.executeUpdate();
    ps.close();
    ps = null;

    // Write the roles into the multi-value table.
    if (!roles.isEmpty()) {
        ps = connection.prepareStatement(
            "INSERT INTO targetapp.\"IIQAccountRoles\" (\"IIQID\", \"RoleName\") " +
            "VALUES (?, ?)");
        for (Object role : roles) {
            ps.setString(1, iiqid);
            ps.setString(2, role.toString());
            ps.addBatch();
        }
        ps.executeBatch();
    }

    result.setStatus(ProvisioningResult.STATUS_COMMITTED);
} catch (Exception e) {
    result.setStatus(ProvisioningResult.STATUS_FAILED);
    result.addError("Create failed: " + e.getMessage());
} finally {
    if (ps != null) {
        try { ps.close(); } catch (Exception e) { }
    }
}

return result;

import java.sql.PreparedStatement;
import java.util.List;
import sailpoint.object.ProvisioningPlan;
import sailpoint.object.ProvisioningPlan.AttributeRequest;
import sailpoint.object.ProvisioningPlan.Operation;
import sailpoint.object.ProvisioningResult;
import sailpoint.tools.Util;

ProvisioningResult result = new ProvisioningResult();

String iiqid = request.getNativeIdentity();
if (Util.isNullOrEmpty(iiqid)) {
    result.setStatus(ProvisioningResult.STATUS_FAILED);
    result.addError("No NativeIdentity, the account cannot be determined.");
    return result;
}

PreparedStatement ps = null;
try {
    List attrs = request.getAttributeRequests();
    if (attrs != null) {
        for (AttributeRequest attr : attrs) {
            String name = attr.getName();
            Object value = attr.getValue();
            Operation op = attr.getOperation();

            if ("roles".equals(name)) {
                // Multi-valued attribute: maintain roles one by one.
                List roles = (value instanceof List)
                            ? (List) value
                            : java.util.Collections.singletonList(value);

                if (Operation.Remove.equals(op)) {
                    ps = connection.prepareStatement(
                        "DELETE FROM targetapp.\"IIQAccountRoles\" " +
                        "WHERE \"IIQID\" = ? AND \"RoleName\" = ?");
                } else {
                    // Add and Set are treated alike: insert unless
                    // already present.
                    ps = connection.prepareStatement(
                        "INSERT INTO targetapp.\"IIQAccountRoles\" " +
                        "(\"IIQID\", \"RoleName\") VALUES (?, ?) " +
                        "ON CONFLICT DO NOTHING");
                }
                for (Object role : roles) {
                    if (role == null) continue;
                    ps.setString(1, iiqid);
                    ps.setString(2, role.toString());
                    ps.addBatch();
                }
                ps.executeBatch();
                ps.close();
                ps = null;

            } else {
                // Single-valued attribute: update the column.
                //
                // The column name comes from the application's
                // schema, not from user input, so it can be
                // interpolated into the statement. It is still
                // checked against the schema so that a faulty
                // configuration does not produce invalid SQL.
                if (schema.getAttributeDefinition(name) == null) {
                    continue;
                }
                ps = connection.prepareStatement(
                    "UPDATE targetapp.\"IIQData\" SET \"" + name + "\" = ?, " +
                    "\"Modified\" = CURRENT_TIMESTAMP WHERE \"IIQID\" = ?");
                ps.setString(1, value != null ? value.toString() : null);
                ps.setString(2, iiqid);
                ps.executeUpdate();
                ps.close();
                ps = null;
            }
        }
    }
    result.setStatus(ProvisioningResult.STATUS_COMMITTED);
} catch (Exception e) {
    result.setStatus(ProvisioningResult.STATUS_FAILED);
    result.addError("Modify failed: " + e.getMessage());
} finally {
    if (ps != null) {
        try { ps.close(); } catch (Exception e) { }
    }
}

return result;

import java.sql.PreparedStatement;
import sailpoint.object.ProvisioningResult;
import sailpoint.tools.Util;

ProvisioningResult result = new ProvisioningResult();

String iiqid = request.getNativeIdentity();
if (Util.isNullOrEmpty(iiqid)) {
    result.setStatus(ProvisioningResult.STATUS_FAILED);
    result.addError("No NativeIdentity, the account cannot be determined.");
    return result;
}

PreparedStatement ps = null;
try {
    // Roles first: the table has no foreign key with CASCADE,
    // otherwise orphaned rows would remain.
    ps = connection.prepareStatement(
        "DELETE FROM targetapp.\"IIQAccountRoles\" WHERE \"IIQID\" = ?");
    ps.setString(1, iiqid);
    ps.executeUpdate();
    ps.close();

    ps = connection.prepareStatement(
        "DELETE FROM targetapp.\"IIQData\" WHERE \"IIQID\" = ?");
    ps.setString(1, iiqid);
    ps.executeUpdate();

    result.setStatus(ProvisioningResult.STATUS_COMMITTED);
} catch (Exception e) {
    result.setStatus(ProvisioningResult.STATUS_FAILED);
    result.addError("Delete failed: " + e.getMessage());
} finally {
    if (ps != null) {
        try { ps.close(); } catch (Exception e) { }
    }
}

return result;

